package com.fasterxml.jackson.core.sym;

import com.fasterxml.jackson.core.JsonFactory;
import com.fasterxml.jackson.core.util.InternCache;
import java.io.*;
import java.math.*;
import java.util.*;
import java.util.Arrays;
import java.util.concurrent.atomic.AtomicReference;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for ByteQuadsCanonicalizer.toString()
 */
public class ByteQuadsCanonicalizer_toString_TriageGen0Test {

    @Test
    public void testToStringEmpty() {
        // Test with an empty canonicalizer (root)
        ByteQuadsCanonicalizer canonicalizer = ByteQuadsCanonicalizer.createRoot();

        String result = canonicalizer.toString();

        // Expected format: [className: size=X, hashSize=Y, P/S/T/Sp pri/sec/ter/spill (=Sum), total:Z]
        // For an empty one: pri=0, sec=0, tert=0, spill=0, total=0, sum=0
        String expectedClassName = ByteQuadsCanonicalizer.class.getName();

        // Since we don't know the exact internal _count and _hashSize values 
        // (they depend on the implementation details of the constructor), 
        // we use regex or contains to verify the structure.

        assertTrue("Result should contain class name", result.contains(expectedClassName));
        assertTrue("Result should contain size", result.contains("size="));
        assertTrue("Result should contain hashSize", result.contains("hashSize="));
        assertTrue("Result should contain counts structure", result.contains("pri/sec/ter/spill"));
        assertTrue("Result should contain total", result.contains("total:"));

        // Verify the math part (pri+sec+tert+spill) matches total if all are 0
        // Format: (=%s), total:%d where %s is the sum
        // For empty: (0), total:0
        assertTrue("Result should correctly show zeroed counts", result.contains("(0), total:0"));

        canonicalizer.release();
    }

    @Test
    public void testToStringWithData() {
        // Test with data to ensure counts are non-zero
        ByteQuadsCanonicalizer canonicalizer = ByteQuadsCanonicalizer.createRoot();

        // Add some names to trigger different levels of the hash table
        // We use different q values to potentially hit different buckets/levels
        canonicalizer.addName("test1", 0x11);
        canonicalizer.addName("test2", 0x22);
        canonicalizer.addName("test3", 0x33);
        canonicalizer.addName("test4", 0x44);

        String result = canonicalizer.toString();

        String expectedClassName = ByteQuadsCanonicalizer.class.getName();
        assertTrue("Result should contain class name", result.contains(expectedClassName));

        // Extract counts to verify the sum logic: (pri+sec+tert+spill) == total
        // Pattern: ... (=%s), total:%d
        // We check if the string contains the counts in a valid format
        // Example: ... 4/0/0/0 (=4), total:4

        // Since we cannot easily predict the exact distribution of pri/sec/ter/spill 
        // without knowing the exact hash algorithm/bucket size, we verify the sum logic via regex
        // The regex looks for: (number), total:number
        String regex = "\\((\\d+)\\), total:(\\d+)";
        java.util.regex.Pattern pattern = java.util.regex.Pattern.compile(regex);
        java.util.regex.Matcher matcher = pattern.matcher(result);

        assertTrue("toString output must match the sum/total pattern", matcher.find());

        int sumValue = Integer.parseInt(matcher.group(1));
        int totalValue = Integer.parseInt(matcher.group(2));

        assertEquals("The sum in parentheses must equal the total count", sumValue, totalValue);

        canonicalizer.release();
    }

    @Test
    public void testToStringWithChild() {
        // Test with a child canonicalizer to ensure class name remains correct
        ByteQuadsCanonicalizer root = ByteQuadsCanonicalizer.createRoot();
        ByteQuadsCanonicalizer child = root.makeChild(0);

        child.addName("childTest", 0xAA);

        String result = child.toString();
        String expectedClassName = ByteQuadsCanonicalizer.class.getName();

        assertTrue("Result should contain class name even for child", result.contains(expectedClassName));

        // Verify the sum logic for the child
        String regex = "\\((\\d+)\\), total:(\\d+)";
        java.util.regex.Matcher matcher = java.util.regex.Pattern.compile(regex).matcher(result);
        assertTrue(matcher.find());
        assertEquals(Integer.parseInt(matcher.group(1)), Integer.parseInt(matcher.group(2)));

        root.release();
        child.release();
    }
}
